class Chan:
    cap: int
    buf: list[int]

def chan_new(cap: int) -> Chan:
    """An empty integer channel that holds at most cap values."""
    pre cap >= 0
    ex chan_new(2).cap == 2
    ex chan_new(2).buf == []
    return Chan(cap, [])

def chan_offer(ch: Chan, v: int) -> tuple[Chan, bool]:
    """Try to enqueue v without blocking. Returns the updated channel and whether v was accepted."""
    post out[1] == (ch.buf.len() < ch.cap)
    ex chan_offer(chan_new(0), 5)[1] == False
    ex chan_offer(chan_new(1), 5)[1] == True
    if ch.buf.len() < ch.cap:
        return (Chan(ch.cap, ch.buf + [v]), True)
    return (ch, False)

def accepted_bound(cap: int, xs: list[int]) -> int:
    """Deterministic upper bound on accepted sends: the smaller of cap and the number of elements."""
    pre cap >= 0
    ex accepted_bound(2, [1, 2, 3]) == 2
    ex accepted_bound(0, [1]) == 0
    ex accepted_bound(5, []) == 0
    if cap < xs.len():
        return cap
    return xs.len()

def accepted(cap: int, xs: list[int]) -> int uses nondet:
    """Attempt to send each element of xs on a channel of capacity cap without blocking. Count the accepted sends, stopping once the channel is full."""
    pre cap >= 0
    post out <= cap and out <= xs.len() and (out == cap or out == xs.len())
    return accepted_bound(cap, xs)
